   - Create a file named `server.js` in the root directory.
   - Set up a basic Express server:
     ```javascript
     const express = require('express');
     const cors = require('cors');
     const dotenv = require('dotenv');

     dotenv.config();

     const app = express();
     app.use(cors());
     app.use(express.json());

     // Define a simple route
     app.get('/', (req, res) => {
       res.send('Movie API');
     });

     const PORT = process.env.PORT || 5000;
     app.listen(PORT, () => {
       console.log(`Server running on port ${PORT}`);
     });
     ```

2. **Create a Route to Fetch Movies:**
   - Create a file named `routes/movies.js`:
     ```javascript
     const express = require('express');
     const axios = require('axios');
     const router = express.Router();

     // Fetch movies from a public API
     router.get('/', async (req, res) => {
       try {
         const response = await axios.get('https://api.themoviedb.org/3/movie/popular?api_key=YOUR_API_KEY');
         res.json(response.data.results);
       } catch (err) {
         res.status(500).json({ message: err.message });
       }
     });

     module.exports = router;
     ```

3. **Use the Routes in the Server:**
   - Update `server.js` to use the movie routes:
     ```javascript
     const movieRoutes = require('./routes/movies');
     app.use('/api/movies', movieRoutes);
     ```

### Step 3: Set Up the Front-End

1. **Create a Movie List Component:**
   - In the `client` directory, create a file named `src/components/MovieList.js`:
     ```javascript
     import React, { useEffect, useState } from 'react';
     import axios from 'axios';

     const MovieList = () => {
       const [movies, setMovies] = useState([]);

       useEffect(() => {
         axios.get('/api/movies')
           .then(response => setMovies(response.data))
           .catch(error => console.error('Error fetching movies:', error));
       }, []);

       return (
         <div>
           <h1>Movie List</h1>
           <ul>
             {movies.map(movie => (
               <li key={movie.id}>
                 <h2>{movie.title}</h2>
                 <p>{movie.overview}</p>
                 <p>Rating: {movie.vote_average}</p>
                 <img src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`} alt={movie.title} />
               </li>
             ))}
           </ul>
         </div>
       );
     };

     export default MovieList;
     ```

2. **Update App.js:**
   - Update `src/App.js` to include the `MovieList` component:
     ```javascript
     import React from 'react';
     import MovieList from './components/MovieList';

     function App() {
       return (
         <div className="App">
           <MovieList />
         </div>
       );
     }

     export default App;
     ```

### Step 4: Run the Application

1. **Start the Back-End Server:**
   - In the root directory, run:
     ```bash
     node server.js
     ```

2. **Start the Front-End Server:**
   - In the `client` directory, run:
     ```bash
     npm start
     ```

### Step 5: Test the Application

- Open your browser and navigate to `http://localhost:3000` to see your movie website in action.

### Additional Features

- **Search Functionality:** Add a search bar to allow users to search for specific movies.
- **Movie Details Page:** Create a detailed page for each movie, including cast, director, and reviews.
- **User Ratings:** Implement a system for users to rate and review movies.
- **Watchlist:** Allow users to create a watchlist of their favorite movies.

